import { readFile } from 'node:fs/promises';

/**
 * Reads a JSON file from disk and returns the parsed value.
 *
 * @param {string | URL} filePath - Path to the JSON file.
 * @returns {Promise<any>} The parsed JSON value.
 * @throws {Error} If the file can't be read or contains invalid JSON.
 */
export async function readJson(filePath) {
  let text;
  try {
    text = await readFile(filePath, 'utf8');
  } catch (err) {
    throw new Error(`Failed to read file "${filePath}": ${err.message}`, { cause: err });
  }

  // Strip a UTF-8 BOM if present, since JSON.parse rejects it
  if (text.charCodeAt(0) === 0xfeff) {
    text = text.slice(1);
  }

  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error(`Invalid JSON in file "${filePath}": ${err.message}`, { cause: err });
  }
}
```

