 * @param {number} [options.timeout=10000] - Per-request timeout in ms.
 * @returns {Promise<Array<{url: string, status: number|null, error: string|null}>>}
 */
async function getStatuses(urls, { method = 'HEAD', timeout = 10000 } = {}) {
  const fetchOne = async (url) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);

    try {
      const res = await fetch(url, { method, signal: controller.signal });
      return { url, status: res.status, error: null };
    } catch (err) {
      return { url, status: null, error: err.name === 'AbortError' ? 'timeout' : err.message };
    } finally {
      clearTimeout(timer);
    }
  };

  // Promise.all preserves input order regardless of completion order.
  return Promise.all(urls.map(fetchOne));
}
```

### Usage

```javascript
