# Fetch URL Statuses in Order

Here's a function that fetches all URLs concurrently (for speed) while preserving the input order in the result:

```javascript
/**
 * Fetches the HTTP response status for each URL, preserving input order.
 * @param {string[]} urls - List of URLs to check.
 * @param {object} [options]
 * @param {number} [options.timeout=10000] - Per-request timeout in ms.
 * @param {RequestInit} [options.fetchOptions] - Extra options passed to fetch().
 * @returns {Promise<Array<{url: string, status: number|null, error: string|null}>>}
 */
async function getStatusesInOrder(urls, { timeout = 10000, fetchOptions = {} } = {}) {
  const fetchOne = async (url) => {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);
    try {
      // HEAD avoids downloading the body; fall back to GET if the server rejects it.
      let res = await fetch(url, { ...fetchOptions, method: 'HEAD', signal: controller.signal });
      if (res.status === 405 || res.status === 501) {
        res = await fetch(url, { ...fetchOptions, method: 'GET', signal: controller.signal });
      }
      return { url, status: res.status, error: null };
    } catch (err) {
      return { url, status: null, error: err.name === 'AbortError' ? 'timeout' : err.message };
    } finally {
      clearTimeout(timer);
    }
  };

  // Promise.all preserves the order of the input array, regardless of completion order.
  return Promise.all(urls.map(fetchOne));
}
```

### Usage

```javascript
const urls = [
  'https://example.com',
  'https://httpstat.us/404',
  'https://this-domain-does-not-exist.invalid',
];

const results = await getStatusesInOrder(urls);
console.log(results);
// [
//   { url: 'https://example.com', status: 200, error: null },
//   { url: 'https://httpstat.us/404', status: 404, error: null },
//   { url: 'https://this-domain-does-not-exist.invalid', status: null, error: 'fetch failed' },
// ]
