```js
/**
 * Fetches each URL and returns its HTTP status code, in the same order as the input.
 * Network failures (DNS, connection refused, etc.) yield `null`.
 */
async function getResponseStatuses(urls, { timeout = 10_000, method = 'GET' } = {}) {
  return Promise.all(
    urls.map(async (url) => {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeout);

      try {
        const response = await fetch(url, {
          method,
          signal: controller.signal,
          redirect: 'follow',
        });
        return response.status;
      } catch {
        return null; // network error or timeout
      } finally {
        clearTimeout(timer);
      }
    })
  );
}

// Example:
const statuses = await getResponseStatuses([
  'https://example.com',
  'https://httpbin.org/status/404',
  'https://nonexistent.invalid',
]);
// => [200, 404, null]
```

**Notes:**

- `Promise.all` preserves the order of the input array regardless of which request finishes first.
- `fetch` only rejects on network-level failures; HTTP error statuses (404, 500, …) resolve normally, so `response.status` is returned as-is.
- `method: 'HEAD'` can be used instead of `'GET'` to avoid downloading response bodies (some servers don't support it, so `GET` is the safer default).
- For very large lists, consider limiting concurrency (e.g., a worker pool) to avoid overwhelming the network or hitting rate limits.

