Adds a timeout, a concurrency cap (so you don't open 1000 sockets), and optional throwing on errors.

```js
async function getResponseStatuses(urls, options = {}) {
  const {
    method = 'GET',
    headers = {},
    timeout = 10_000,      // ms per request
    concurrency = 10,      // max simultaneous requests
    throwOnError = false,  // true → reject instead of returning null
  } = options;

  const results = new Array(urls.length);
  let nextIndex = 0;

  async function worker() {
    while (true) {
      const i = nextIndex++;
      if (i >= urls.length) return;

      const url = urls[i];
      try {
        const res = await fetch(url, {
          method,
          headers,
          redirect: 'follow',
          signal: AbortSignal.timeout(timeout),
        });

        // We only care about the status line; release the connection.
        if (res.body) await res.body.cancel().catch(() => {});

        results[i] = res.status;
      } catch (err) {
        if (throwOnError) throw err;
        results[i] = null;
      }
    }
  }

  const workerCount = Math.min(concurrency, urls.length || 1);
  await Promise.all(Array.from({ length: workerCount }, () => worker()));

  return results;
}
