## Production version (timeouts, concurrency cap, error detail)

```js
const DEFAULT_TIMEOUT = 10_000; // ms

/**
 * Fetch a list of URLs and return their HTTP status codes, in the same order.
 *
 * @param {string[]} urls
 * @param {object}   [options]
 * @param {number}   [options.timeout=10000]    Per-request timeout in ms.
 * @param {number}   [options.concurrency=10]    Max simultaneous requests.
 * @param {string}   [options.method='GET']      'HEAD' is lighter on bandwidth.
 * @param {object}   [options.headers]
 * @param {AbortSignal} [options.signal]         Cancel the whole batch.
 * @returns {Promise<Array<number|null>>}        null = request failed, not an HTTP error.
 */
async function getStatuses(urls, options = {}) {
  const {
    timeout = DEFAULT_TIMEOUT,
    concurrency = 10,
    method = 'GET',
    headers,
    signal,
  } = options;

  const results = new Array(urls.length);
  let cursor = 0;

  async function fetchStatus(url) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);
    const forwardAbort = () => controller.abort();
    signal?.addEventListener('abort', forwardAbort, { once: true });

    try {
      const res = await fetch(url, {
        method,
        headers,
        redirect: 'follow',
        signal: controller.signal,
      });
      // We only care about the status; don't let the body stream leak.
      res.body?.cancel?.().catch(() => {});
      return res.status;
    } catch {
      return null; // timeout, DNS error, TLS error, aborted, etc.
    } finally {
      clearTimeout(timer);
      signal?.removeEventListener('abort', forwardAbort);
    }
  }

  async function worker() {
    while (cursor < urls.length) {
      const index = cursor++;
      results[index] = await fetchStatus(urls[index]);
    }
  }

  const workers = Array.from(
    { length: Math.max(1, Math.min(concurrency, urls.length)) },
    () => worker()
  );

  await Promise.all(workers);
  return results;
}
```

